body{margin:0;font-family:"Open Sans","Inter","Segoe UI",Arial,sans-serif;color:#e2e8f0;background:#1e293b;-webkit-font-smoothing:antialiased;}
.wrap{position:relative;box-sizing:border-box;min-height:100%;}
.close{position:absolute;top:15px;right:15px;width:34px;height:34px;border:none;background:rgba(148,163,184,.12);color:#cbd5e1;font-size:17px;line-height:1;cursor:pointer;border-radius:9px;z-index:3;transition:.15s;}
.close:hover{background:#ef4444;color:#fff;}
.hero{padding:28px 34px 22px;background:radial-gradient(130% 150% at 0% 0%,#26456f 0%,#1e293b 58%);border-bottom:1px solid #334155;}
.eyebrow{display:flex;align-items:center;gap:10px;color:#9fbce6;font-size:11px;font-weight:800;letter-spacing:.13em;text-transform:uppercase;margin-bottom:12px;}
.eyebrow .env{width:28px;height:28px;border-radius:8px;background:rgba(96,165,250,.18);display:flex;align-items:center;justify-content:center;font-size:15px;}
.subject{font-size:19px;font-weight:800;color:#f8fafc;line-height:1.4;padding-right:42px;word-break:break-word;letter-spacing:-.01em;}
.badges{display:flex;gap:9px;margin-top:16px;flex-wrap:wrap;}
.badge{display:inline-flex;align-items:center;gap:7px;padding:5px 13px;border-radius:20px;font-size:12px;font-weight:700;}
.badge .d{width:7px;height:7px;border-radius:50%;}
.b-error{background:rgba(248,113,113,.15);color:#fca5a5;} .b-error .d{background:#f87171;}
.b-warning{background:rgba(251,191,36,.15);color:#fcd34d;} .b-warning .d{background:#fbbf24;}
.b-info{background:rgba(96,165,250,.15);color:#93c5fd;} .b-info .d{background:#60a5fa;}
.b-default{background:rgba(148,163,184,.15);color:#cbd5e1;} .b-default .d{background:#94a3b8;}
.body{padding:24px 34px 34px;}
.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;}
.card{background:#0f172a;border:1px solid #26344b;border-radius:11px;padding:13px 15px;transition:.15s;}
.card:hover{border-color:#3b5378;}
.card.wide{grid-column:1 / -1;}
.card .lbl{color:#7d8ea6;font-size:10.5px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;margin-bottom:5px;}
.card .val{color:#e8eef7;font-size:14px;font-weight:500;word-break:break-word;line-height:1.4;}
.section{display:flex;align-items:center;gap:12px;margin:28px 0 14px;color:#aab7c9;font-size:11.5px;font-weight:800;letter-spacing:.09em;text-transform:uppercase;}
.section:before,.section:after{content:"";height:1px;background:#334155;flex:1;}
.events-empty{display:flex;flex-direction:column;align-items:center;gap:10px;padding:30px;border:1px dashed #334155;border-radius:12px;color:#64748b;background:#0f172a;}
.events-empty .ico{font-size:30px;opacity:.55;}
.events-empty .txt{font-size:13px;font-style:italic;}
.evt{display:flex;align-items:flex-start;gap:12px;background:#0f172a;border:1px solid #26344b;border-radius:10px;padding:12px 15px;margin-bottom:8px;}
.evt .d{width:9px;height:9px;border-radius:50%;margin-top:5px;flex:0 0 auto;background:#475569;}
.evt.err .d{background:#f87171;} .evt.warn .d{background:#fbbf24;} .evt.on .d{background:#22c55e;}
.evt .en{flex:1;min-width:0;}
.evt .nm{font-size:13px;font-weight:700;color:#e8eef7;text-transform:capitalize;}
.evt .rs{font-size:12px;color:#94a3b8;margin-top:3px;word-break:break-word;}
.evt .tm{font-size:12px;color:#7d8ea6;white-space:nowrap;}
.skel{padding:60px;text-align:center;color:#94a3b8;}

