import React, { useState, useEffect } from "https://esm.sh/react@18.2.0";
import ReactDOM from "https://esm.sh/react-dom@18.2.0";

const FIELDS = [
  ["id", "ID"], ["customer_name", "Customer"], ["customer_id", "Customer ID"],
  ["email_address", "Email Address", true], ["email_type", "Email Type"],
  ["status", "Email Status"], ["type", "Status Type"],
  ["status_date", "Status Date"], ["created_at", "Created At"], ["updated_at", "Updated At"],
  ["tracking_id", "SendGrid Tracking ID", true]
];

function fmtTs(v) {
  if (v == null) return "";
  if (typeof v === "number") { try { return new Date(v * 1000).toLocaleString(); } catch (e) { return String(v); } }
  return String(v);
}

function App() {
  const [model, setModel] = useState(appsmith.model || {});
  useEffect(() => {
    const update = () => setModel({ ...(appsmith.model || {}) });
    update();
    if (typeof appsmith.onModelChange === "function") appsmith.onModelChange(update);
    const id = setInterval(update, 400);
    return () => clearInterval(id);
  }, []);

  const close = () => { if (typeof appsmith.triggerEvent === "function") appsmith.triggerEvent("onClose"); };
  const row = model && model.row;

  const closeBtn = React.createElement("button", { className: "close", onClick: close }, "\u2715");

  if (model.isLoading) return React.createElement("div", { className: "wrap" }, closeBtn, React.createElement("div", { className: "skel" }, "Loading details..."));
  if (!row) return React.createElement("div", { className: "wrap" }, closeBtn, React.createElement("div", { className: "skel" }, "No record selected"));

  const t = (row.type == null ? "" : String(row.type)).toLowerCase();
  const tcls = t === "error" ? "badge b-error" : t === "warning" ? "badge b-warning" : t === "information" ? "badge b-info" : "badge b-default";
  const s = (row.status == null ? "" : String(row.status)).toLowerCase();
  const scls = (s === "bounce" || s === "dropped" || s === "blocked") ? "badge b-error" : s === "deferred" ? "badge b-warning" : "badge b-default";

  let events = row.sendgrid_events;
  if (typeof events === "string") { try { events = JSON.parse(events); } catch (e) { events = null; } }
  if (!Array.isArray(events)) events = [];

  const eventsSection = events.length === 0
    ? React.createElement("div", { className: "events-empty" },
        React.createElement("div", { className: "ico" }, "\uD83D\uDCED"),
        React.createElement("div", { className: "txt" }, "No delivery events recorded"))
    : events.map(function (ev, i) {
        const name = (ev && (ev.event || ev.type)) || "event";
        const nl = String(name).toLowerCase();
        const kind = (nl === "bounce" || nl === "dropped" || nl === "blocked") ? "err" : (nl === "deferred" ? "warn" : "on");
        const ts = ev && (ev.timestamp != null ? ev.timestamp : ev.time);
        const extra = ev && (ev.reason || ev.response || ev.status || "");
        return React.createElement("div", { className: "evt " + kind, key: i },
          React.createElement("div", { className: "d" }),
          React.createElement("div", { className: "en" },
            React.createElement("div", { className: "nm" }, String(name)),
            extra ? React.createElement("div", { className: "rs" }, String(extra)) : null),
          React.createElement("div", { className: "tm" }, ts != null ? fmtTs(ts) : "\u2014"));
      });

  return React.createElement("div", { className: "wrap" },
    closeBtn,
    React.createElement("div", { className: "hero" },
      React.createElement("div", { className: "eyebrow" },
        React.createElement("span", { className: "env" }, "\u2709"),
        React.createElement("span", null, "Communication Detail")),
      React.createElement("div", { className: "subject" }, (row.email_subject != null ? String(row.email_subject).trim() : "") || "(no subject)"),
      React.createElement("div", { className: "badges" },
        row.status ? React.createElement("span", { className: scls }, React.createElement("span", { className: "d" }), row.status) : null,
        row.type ? React.createElement("span", { className: tcls }, React.createElement("span", { className: "d" }), row.type) : null)),
    React.createElement("div", { className: "body" },
      React.createElement("div", { className: "grid" },
        FIELDS.map((f) => React.createElement("div", { className: "card" + (f[2] ? " wide" : ""), key: f[0] },
          React.createElement("div", { className: "lbl" }, f[1]),
          React.createElement("div", { className: "val" }, (row[f[0]] == null || row[f[0]] === "") ? "\u2014" : String(row[f[0]]))))),
      React.createElement("div", { className: "section" }, "SendGrid Events (" + events.length + ")"),
      eventsSection));
}

ReactDOM.render(React.createElement(App, null), document.getElementById("root"));

